<script setup lang="ts">
import {ref,computed,onMounted} from 'vue';import {get} from '../api/client';import {can} from '../permissions'
const props=defineProps<{view:string}>(),rows=ref<any[]>([]),detail=ref<any>(null),q=ref(''),page=ref(1),error=ref('')
const titles:Record<string,string>={notices:'通知管理',history:'通知历史',replacements:'信息更替',strategy:'内容推荐策略'}
const filtered=computed(()=>rows.value.filter(r=>(props.view==='replacements'||r.contentType==='NOTICE')&&r.title.includes(q.value))),visible=computed(()=>filtered.value.slice((page.value-1)*20,page.value*20))
async function inspect(id:string){error.value='';try{detail.value=await get('/api/v1/admin/articles/'+id)}catch(e){error.value=(e as Error).message}}
onMounted(async()=>{try{rows.value=await get('/api/v1/admin/articles')}catch(e){error.value=(e as Error).message}})
</script><template><section><h1>{{ titles[props.view] }}</h1><p class="error" role="alert">{{ error }}</p><div v-if="view==='strategy'" class="panel"><h2>当前排序规则</h2><p>资讯列表按关注、置顶、重要度、热点、新鲜度和待生效临近程度计分，再按发布时间和编号排序。首页默认展示热点资讯；搜索使用完整条件筛选。</p><p>重要度 0–5、热点 0–10、新鲜度 0–5，调整均通过资讯修订、审核、发布生效。单独推荐位由内容运营管理。</p><p>曝光限制只影响推荐流，不限制搜索；同一快照分页保留排序，内容撤下后会即时剔除。</p><router-link to="/articles">编辑资讯排序属性</router-link> · <router-link v-if="can('yunji:operation:manage')" to="/recommendations">管理推荐位</router-link></div><template v-else><p class="muted">与资讯审核共用版本和权限，当前加载最多 200 条。更替需在原资讯详情选择已发布目标并确认。</p><div class="panel actions"><input v-model="q" placeholder="筛选标题" @input="page=1"/><router-link to="/articles">创建资讯 / 通知</router-link></div><div class="panel scroll"><table><thead><tr><th>标题</th><th>状态</th><th>版本</th><th>操作</th></tr></thead><tbody><tr v-for="r in visible" :key="r.id"><td>{{ r.title }}</td><td>{{ r.status }}</td><td>{{ r.versionNo }}</td><td><button class="quiet" @click="inspect(r.id)">查看历史与审核</button><router-link :to="'/articles?id='+r.id">{{ view==='replacements'?'打开更替操作':'修订与发布' }}</router-link></td></tr></tbody></table><p v-if="!visible.length">暂无匹配内容</p><div class="actions"><button class="quiet" :disabled="page===1" @click="page--">上一页</button><span>{{ page }}</span><button class="quiet" :disabled="page*20>=filtered.length" @click="page++">下一页</button></div></div><div v-if="detail" class="panel"><h2>{{ detail.title }}</h2><div v-for="v in detail.versions" :key="v.id" class="version"><h3>版本 {{ v.versionNo }} · {{ v.reviewState }}</h3><p>{{ v.title }}</p><p>{{ v.changeSummary||'无修订说明' }}</p><p>{{ v.effectiveFrom||'不限开始' }} — {{ v.effectiveTo||'不限结束' }}</p></div><h3>审核日志</h3><p v-for="r in detail.reviews" :key="r.id">{{ r.action }} · {{ r.createdAt }} · {{ r.comment||'无说明' }}</p></div></template></section></template>
